using SparkFlow.Server.Application.Services; namespace SparkFlow.Server.Application.Features.Sessions.FailSession; public sealed class FailSessionHandler { private readonly SessionService _service; public FailSessionHandler(SessionService service){_service=service;} public Task<bool> Handle(FailSessionCommand command, CancellationToken cancellationToken=default)=>_service.FailAsync(command.SessionId,command.Error,cancellationToken);}
